-- #1656 - VendorConfig.showAllergenNotice: per-vendor storefront notice telling shoppers to ask
-- the store about allergens before ordering (stopgap until structured allergen data, #1653).
--
-- HAND-AUTHORED, not generated by `prisma migrate dev --create-only`: that command refuses on the
-- dev database (#895) and offers only `migrate reset`.
--
-- Purely additive: one boolean column defaulting to false, so no vendor's storefront changes until
-- an admin ticks the setting in /staff/storefront.

-- AlterTable
ALTER TABLE "VendorConfig" ADD COLUMN     "showAllergenNotice" BOOLEAN NOT NULL DEFAULT false;
